   "syn": "秀外慧中的好媳妇陈思珍（蒋天流 饰）自与丈夫唐志远（张伐 饰）结婚后，便把家里的人际关系处理得很好，持家有道。一日，思珍的弟弟陈思瑞（韩非 饰）从台湾到上海省亲，邂逅志远的妹妹唐志琴（汪漪 饰），两人一见钟情。然而因为陈父（石挥 饰）不肯资助自己筹办公司的志远，却极力反对这桩亲事。思珍只得谎称唐家存有金条美钞，陈父才同意资助志远办起公司。不料发迹致富的志远却有了外遇，与姨太太（上官云珠 饰）有染。思珍为了顾全丈夫名誉，只得委曲求全。未几，志远破产，谎言败露，两家人也因此闹翻。终于，思珍决定与志远离婚，却在律师事务所遇见了秘密登记结婚的思瑞、志琴两人。面对真心相爱的一对有情人，思珍该何去何从。",
   "bio": "桑弧是文华影业的重要导演，曾与张爱玲合作《不了情》《太太万岁》，后来执导《梁山伯与祝英台》《祝福》等作品。他擅长通过人物关系与生活细节展开叙事，使轻快的喜剧场面保留现实中的人情压力。",
   "st": "张爱玲为影片创作原创剧本，把故事集中在一个普通太太维持家庭关系的日常之中。影片于 1947 年在上海拍摄、上映。除了人物对白，也可以留意旗袍、住宅与社交场合：这些细节和角色的阶层位置紧密相连。",
