   "syn": "长久以来，剧作家大卫（约翰·库萨克 John Cusack 饰）都过着郁郁不得志的生活，艺术家特有的清高让他对如今腐败混乱的话剧界充满了失望之情。为了讨好情妇奥利芙（詹妮弗·提莉 Jennifer Tilly 饰），黑帮大佬看中了名不见经传的大卫的剧本想要投资，作为前提条件，大卫必须让奥利芙饰演主角。虽然奥利芙唠叨的个性和蹩脚的演技让大卫深感抓狂，但在利益面前，他痛苦地屈服了。就这样，一个奇怪的剧组诞生了。\n\n剧本的漏洞，女演员们之间的矛盾，男主演日益肥胖的身材都让大卫感到绝望，但令他惊奇的是，一直监视着奥利芙的保镖契奇（查兹·帕尔明特瑞 Chazz Palminteri 饰）在无意中展现了过人的编剧才能。在契奇的帮助下，被改写的剧本居然获得了盛大的成功，与此同时，契奇对由自己操刀的剧本展现出的病态执着和剧组里混乱的男女关系让大卫陷入了另一个困境……",
   "bio": "伍迪·艾伦是美国导演、编剧与演员，代表作包括《安妮·霍尔》《曼哈顿》《汉娜姐妹》《午夜巴黎》。他常把人物的自我辩护、关系中的不安和艺术趣味写进喜剧，通过密集的对话展开道德与身份的尴尬。",
   "st": "影片由艾伦与道格拉斯·麦格拉斯共同编剧。它把一出戏从筹资到排练的过程，写成关于才华、署名与妥协的后台喜剧。演员、剧作家和出资人都声称自己在维护作品，各自理解的“艺术”却很不一样。",
