   "syn": "伊朗的偏僻山村小学里，一群孩子在课堂里聆听老师讲课。在检查作业的时候，老师发现穆罕德屡次没有完成家庭作业，于是严厉地批评了他，说如若再犯立马开除。老师对学生强调这是帮助他们树立良好的规矩。当天放学后，小男孩阿穆德却赫然发现自己把同桌穆罕德的作业本带回了家。听懂了老师的谆谆善诱，所以阿穆德明白这作业本就是穆罕德继续听讲的凭证。为了把作业本还给同桌，阿穆德曾希望母亲和祖父可以施以援手，但是均告失败。所以，他只能孤身前行，到对面大山里的村落去寻找同桌，归还作业本。然而，由于不认识同桌的家，所以他处处碰壁，遭遇到了无法想象的艰难险阻……",
   "bio": "阿巴斯·基亚罗斯塔米是伊朗导演、编剧，代表作包括《特写》《樱桃的滋味》《随风而逝》。《何处是我朋友的家》与《生生长流》《橄榄树下的情人》构成“柯克三部曲”，以不同方式重新观看同一片地方与生活。",
   "st": "影片是“柯克三部曲”的起点，以孩子寻找作业本主人的行动贯穿一天。它不靠复杂情节推进，而是让道路、询问、等待和反复走错方向积累紧张感。成人世界的规则，也在这个过程中显露出与孩子的责任感之间的距离。",
