   "syn": "评论家亚历山大（厄兰·约瑟夫森 Erland Josephson 饰）在瑞典的家中庆祝自己的五十岁生日，年幼的小儿子刚做完咽喉手术不能发声。两人在静默中种下一株树苗期待它生出绿色的枝叶，然而就在当天晚上，电台广播了一则发射核导弹的消息，第三次世界大战即将爆发。绝望的亚历山大向上帝祈祷不要发生战争，甚至他愿意奉献自己的一切来阻止世界末日的来临。期待世界重生的亚历山大在心力交瘁的情况下，烧毁了自己的房子。在熊熊大火中，亚历山大被救护车送进了医院。小儿子来到岸边继续为他们共同栽种的树苗浇水，一切似乎又恢复了平静。",
   "bio": "安德烈·塔可夫斯基是苏联导演，七部长片包括《伊万的童年》《安德烈·卢布廖夫》《飞向太空》《镜子》《潜行者》《乡愁》《牺牲》。他也著有《雕刻时光》，以持续的镜头、自然元素与记忆中的空间探索人的精神生活。",
   "st": "《牺牲》是塔可夫斯基的最后一部长片，在瑞典拍摄，斯文·尼克维斯特担任摄影，厄兰·约瑟夫森主演。影片把家庭的一天与关于毁灭、信仰和付出的疑问放在一起，许多关键段落通过人物的移动和长时间的等待展开。",
