   "syn": "「法国新浪潮祖母」阿涅斯·瓦尔达与街头艺术家J.R.驾驶着小货车穿越法国的村庄。一路上他们拍摄下所遇到的人物，然后在房子和工厂的墙上涂抹告示牌尺寸大小的肖像画。",
   "bio": "阿涅斯·瓦尔达是法国电影导演与视觉艺术家，代表作包括《五至七时的克莱奥》《天涯沦落女》《拾穗者》。JR 是以公共空间巨幅摄影项目闻名的法国艺术家。本片让电影与街头摄影共同参与对普通人的观看。",
   "st": "在戛纳访谈中，两人介绍，合作最初只是一个乡村短片计划，后来随着相遇不断延伸。他们没有预先写定剧情，而是先选择地方或主题，再让现场的人与事影响拍摄。影片中的轻松交谈，也来自这种共同工作的方法。",
