   "syn": "八岁的托哈在开罗一户富裕人家做童工女仆，和雇主的女儿奈莉一起长大，成了最亲近的玩伴。奈莉的生日快到了，从没过过生日的托哈一心想为她办一场完美的派对，好像这样也能分到一点属于自己的快乐。\n\n随着她与奈莉的母亲莱拉越走越近，主人与佣人之间的界线开始模糊。可派对越接近，托哈越清楚地意识到，自己并不属于这个家，也不属于这场派对。整个故事发生在一天之内。",
   "bio": "萨拉·戈赫尔是埃及裔美国导演、编剧，曾以制片人和导演身份参与漫威剧集《月光骑士》。《生日快乐》是她的长片首作，与穆罕默德·迪亚卜共同编剧，在翠贝卡电影节首映即获多项大奖，并代表埃及角逐奥斯卡最佳国际影片。",
   "st": "影片以孩子的视线观察开罗的阶层秩序：雇主家的厨房、客厅与派对现场，对托哈来说是同一栋房子里截然不同的世界。主创把全部故事压缩在一天之内，让一场生日派对的筹备过程，慢慢显露出童工、阶层与亲密关系之间的张力。小演员朵哈·拉马丹担纲主演。",
