   "syn": "在北京待了多年的年轻导演桑吉回到拉萨，想用自己的第一部长片重现少女时代。拍摄一点点推进，她和父亲之间没解开的结、童年好友拉姆曾经的遭遇，也跟着浮了上来。\n\n一次偶然的重逢，让两个女孩对同一段过去的不同记忆正面相撞。影片在拍摄现场与回忆之间来回穿梭，用一个夜晚连起三个夏天。片名「林卡」是拉萨人夏天到林间野餐、过林卡的传统。",
   "bio": "岗珍是藏族编剧、导演。她的短片《Orlo with Karma》聚焦拉萨年轻一代，入选 2025 年 FIRST 青年电影展与温哥华国际电影节。《一个夜晚与三个夏天》是她的长片首作，曾参加上海国际电影节创投训练营与 WIP 单元、FIRST 青年电影展 WIP 市场。",
   "st": "影片自 2020 年起在拉萨与上海拍摄，被称为首部聚焦西藏当代城市生活的长片。主创用「拍电影的电影」结构，让桑吉的拍摄与真实回忆相互干扰，追问记忆的不稳定与「谁的版本才算真相」。片中大部分角色由非职业演员出演。",
