   "syn": "医疗快递员布莱恩（奥斯汀·艾布拉姆斯 饰）接到任务，要把一批货物送进浣熊市。他抵达时，病毒正在城中失控扩散，整座城市在一夜之间沦陷，变异的怪物在街头四处追猎活人。布莱恩被困在这场浩劫里，只能在混乱中寻找出路，想办法活着离开。",
