   "syn": "曾在网上攻击冲浪教练的青年，阴差阳错成为对方的学生。现实里的相处逐渐改变了他的成见，浪花、训练与误会之间，也萌生一段出人意料的感情。",
   "bio": "冯志强是香港导演、编剧，曾参与《少林足球》《喜剧之王》等影片编剧，导演作品包括《悬红》《犯罪现场》。他在本片以网络误解和冲浪训练组织一段爱情喜剧。",
   "st": "故事由网络争执引出线下相处。冲浪提供了离开键盘、共同面对身体与自然的机会，让成见的瓦解发生在具体的互动之中。",
