   "bio": "克里斯蒂安·佩措尔德是德国导演、编剧，1960年生，柏林学派代表人物之一。他曾凭《Barbara》（2012）与《Afire》（2023）两度获柏林国际电影节银熊奖，《Phoenix》《Transit》同样广受关注。",
   "st": "影片入围2025年戛纳电影节导演双周单元，片长仅86分钟。",
