   "syn": "二十岁那年，约阿希姆出人意料地被慕尼黑那所著名的表演学校录取，并搬进了祖父母英格和赫尔曼的别墅。在表演学校种种奇特的挑战与祖父母那些古怪、多半伴着酒精的日常仪式之间，约阿希姆努力在这个世界上寻找自己的位置——却不知道自己在这其中究竟扮演着怎样的角色。",
