   "bio": "西蒙·范霍文是德国导演、编剧，1972年生于慕尼黑，2016年的喜剧《Willkommen bei den Hartmanns》是德国近年最卖座的影片之一。本片改编自约阿希姆·迈尔霍夫的畅销小说，片中祖母由他的母亲森塔·伯格饰演。",
