   "syn": "十四年前，电影人丹妮拉·马尼亚尼·惠勒在一次未遂的杀害女性（femicide）事件中幸存下来。如今，她回顾自己人生中那段时光的关键时刻。在慕尼黑和里约热内卢之间往返旅行中，她寻访了当时在她身边的某些人，并提出那些多年来一直萦绕在她心头的疑问。精心构图的银幕画面勾勒出她所经历的一切的复杂图景。",
